import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

function DriverDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [availableDeliveries, setAvailableDeliveries] = useState([]);
  const [activeJobs, setActiveJobs] = useState([]);
  const [history, setHistory] = useState([]);
  const [earnings, setEarnings] = useState({ total: 0, weekly: 0, today: 0, perDelivery: 20, totalDeliveries: 0 });
  const [loading, setLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(true);
  const [currentLocation, setCurrentLocation] = useState({ lat: -1.286389, lng: 36.817223, address: 'Nairobi, Kenya' });
  const [selectedJob, setSelectedJob] = useState(null);
  const [showLocationModal, setShowLocationModal] = useState(false);
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(2);
  const [filterStatus, setFilterStatus] = useState('all');

  // Vehicle info state
  const [vehicleInfo, setVehicleInfo] = useState({
    model: user?.vehicleModel || 'Toyota Camry',
    color: user?.vehicleColor || 'White',
    plate: user?.vehiclePlate || 'KCA 123A',
    year: 2022
  });

  // Driver stats
  const [driverStats, setDriverStats] = useState({
    rating: 4.9,
    totalRatings: 128,
    acceptanceRate: 98,
    onTimeRate: 96,
    totalDistance: 1250,
    totalHours: 84
  });

  const token = localStorage.getItem('token');

  // Sample notifications
  const notifications = [
    { id: 1, type: 'new_delivery', title: 'New Delivery Available!', message: 'Pickup from John Doe - Oil Change', time: '2 min ago', read: false, icon: '📦' },
    { id: 2, type: 'earning', title: 'Weekly Earnings', message: 'You earned $240 this week', time: '1 hour ago', read: false, icon: '💰' }
  ];

  useEffect(() => {
    fetchAllData();
    // Get user's location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        setCurrentLocation({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
          address: 'Current Location'
        });
        updateDriverLocation(position.coords.latitude, position.coords.longitude);
      });
    }
    const interval = setInterval(fetchAllData, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      // Fetch available deliveries
      const availRes = await fetch('http://localhost:5000/api/driver/available', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const availData = await availRes.json();
      if (availData.success) setAvailableDeliveries(availData.deliveries);

      // Fetch active jobs
      const jobsRes = await fetch('http://localhost:5000/api/driver/jobs', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const jobsData = await jobsRes.json();
      if (jobsData.success) setActiveJobs(jobsData.jobs);

      // Fetch history
      const historyRes = await fetch('http://localhost:5000/api/driver/history', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const historyData = await historyRes.json();
      if (historyData.success) setHistory(historyData.history);

      // Fetch earnings
      const earningsRes = await fetch('http://localhost:5000/api/driver/earnings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const earningsData = await earningsRes.json();
      if (earningsData.success) setEarnings(earningsData.earnings);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const updateDriverLocation = async (lat, lng) => {
    try {
      await fetch('http://localhost:5000/api/driver/location', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ lat, lng, address: currentLocation.address })
      });
    } catch (error) {
      console.error('Error updating location:', error);
    }
  };

  const updateDriverStatus = async (online) => {
    try {
      const res = await fetch('http://localhost:5000/api/driver/status', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ isOnline: online })
      });
      const data = await res.json();
      if (data.success) {
        setIsOnline(online);
        toast.success(online ? 'You are now online!' : 'You are now offline');
      }
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const acceptDelivery = async (deliveryId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/driver/accept/${deliveryId}`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Delivery accepted!');
        fetchAllData();
        setUnreadCount(prev => Math.max(0, prev - 1));
      } else {
        toast.error(data.error || 'Failed to accept');
      }
    } catch (error) {
      toast.error('Error accepting delivery');
    }
  };

  const updateDeliveryStatus = async (deliveryId, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/driver/delivery/${deliveryId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Delivery marked as ${status}!`);
        fetchAllData();
        setSelectedJob(null);
      } else {
        toast.error('Failed to update status');
      }
    } catch (error) {
      toast.error('Error updating status');
    }
  };

  const updateVehicleInfo = async (e) => {
    e.preventDefault();
    try {
      // API call to update vehicle info
      toast.success('Vehicle info updated!');
      setShowVehicleModal(false);
    } catch (error) {
      toast.error('Failed to update vehicle');
    }
  };

  const markNotificationRead = (id) => {
    setUnreadCount(prev => Math.max(0, prev - 1));
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      'in-progress': '#3b82f6',
      completed: '#8b5cf6',
      cancelled: '#ef4444',
      'driver-assigned': '#8b5cf6',
      pickup: '#3b82f6',
      'en-route': '#10b981'
    };
    const labels = {
      pending: '⏳ Pending',
      confirmed: '✓ Confirmed',
      'in-progress': '🔧 In Progress',
      completed: '✅ Completed',
      cancelled: '❌ Cancelled',
      'driver-assigned': '🚗 Assigned',
      pickup: '📍 Pickup',
      'en-route': '🚚 En Route'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const getDistanceText = () => {
    const distances = ['0.5 miles away', '1.2 miles away', '0.8 miles away', '1.5 miles away', '2.1 miles away'];
    return distances[Math.floor(Math.random() * distances.length)];
  };

  const getEtaText = () => {
    const etas = ['5-10 min', '10-15 min', '8-12 min', '12-18 min', '15-20 min'];
    return etas[Math.floor(Math.random() * etas.length)];
  };

  // Filter history based on status
  const filteredHistory = filterStatus === 'all' ? history : history.filter(h => h.status === filterStatus);

  // Calculate today's earnings
  const todayEarnings = earnings.today || Math.floor(Math.random() * 100) + 50;

  return (
    <div style={styles.dashboard}>
      <ToastContainer position="top-right" />

      {/* Header */}
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🚗💨</span>
          <div>
            <h1 style={styles.logoText}>Car Care Connect - Driver</h1>
            <div style={styles.headerSubtitle}>
              {user?.firstName} {user?.lastName} · ⭐ {driverStats.rating} · 📍 {currentLocation.address.split(',')[0]}
            </div>
          </div>
        </div>

        <div style={styles.headerRight}>
          {/* Online/Offline Toggle */}
          <button style={{ ...styles.onlineToggle, backgroundColor: isOnline ? '#10b981' : '#ef4444' }} onClick={() => updateDriverStatus(!isOnline)}>
            <span style={styles.onlineDot}></span>
            {isOnline ? 'Online' : 'Offline'}
          </button>

          {/* Location Button */}
          <button style={styles.locationBtn} onClick={() => setShowLocationModal(true)}>
            📍
          </button>

          {/* Notification Bell */}
          <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>
            🔔
            {unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}
          </div>

          <div style={styles.userInfo}>
            <img src={`https://ui-avatars.com/api/?background=2563eb&color=fff&name=${user?.firstName}`} alt="avatar" style={styles.avatar} />
            <button onClick={onLogout} style={styles.logoutButton}>🚪</button>
          </div>
        </div>
      </div>

      {/* Notification Dropdown */}
      {showNotifications && (
        <div style={styles.notificationDropdown}>
          <div style={styles.notificationHeader}>
            <h3>🔔 Notifications</h3>
            <button style={styles.markAllRead}>Mark all read</button>
          </div>
          {notifications.map(notif => (
            <div key={notif.id} style={{ ...styles.notificationItem, opacity: notif.read ? 0.6 : 1 }} onClick={() => markNotificationRead(notif.id)}>
              <span style={styles.notificationIconSmall}>{notif.icon}</span>
              <div style={styles.notificationContent}>
                <div style={styles.notificationTitle}>{notif.title}</div>
                <div style={styles.notificationMessage}>{notif.message}</div>
                <div style={styles.notificationTime}>{notif.time}</div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Stats Cards */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}><h3>💰 Today</h3><p style={styles.statNumber}>${todayEarnings}</p></div>
        <div style={styles.statCard}><h3>📊 Weekly</h3><p style={styles.statNumber}>${earnings.weekly || 0}</p></div>
        <div style={styles.statCard}><h3>🏆 Total</h3><p style={styles.statNumber}>${earnings.total || 0}</p></div>
        <div style={styles.statCard}><h3>📦 Deliveries</h3><p style={styles.statNumber}>{earnings.totalDeliveries || 0}</p></div>
        <div style={styles.statCard}><h3>⭐ Rating</h3><p style={styles.statNumber}>{driverStats.rating}</p></div>
        <div style={styles.statCard}><h3>✅ Acceptance</h3><p style={styles.statNumber}>{driverStats.acceptanceRate}%</p></div>
      </div>

      {/* Quick Stats Bar */}
      <div style={styles.quickStats}>
        <div style={styles.quickStat}><span>🚗</span> Online: {isOnline ? 'Yes' : 'No'}</div>
        <div style={styles.quickStat}><span>📦</span> Available: {availableDeliveries.length}</div>
        <div style={styles.quickStat}><span>🚚</span> Active: {activeJobs.length}</div>
        <div style={styles.quickStat}><span>⏱️</span> Online Time: {driverStats.totalHours}h</div>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'available' ? styles.activeTab : {})}} onClick={() => setActiveTab('available')}>📦 Available ({availableDeliveries.length})</button>
        <button style={{...styles.tab, ...(activeTab === 'active' ? styles.activeTab : {})}} onClick={() => setActiveTab('active')}>🚗 Active ({activeJobs.length})</button>
        <button style={{...styles.tab, ...(activeTab === 'history' ? styles.activeTab : {})}} onClick={() => setActiveTab('history')}>📋 History</button>
        <button style={{...styles.tab, ...(activeTab === 'earnings' ? styles.activeTab : {})}} onClick={() => setActiveTab('earnings')}>💰 Earnings</button>
        <button style={{...styles.tab, ...(activeTab === 'vehicle' ? styles.activeTab : {})}} onClick={() => setActiveTab('vehicle')}>🚗 Vehicle</button>
        <button style={{...styles.tab, ...(activeTab === 'profile' ? styles.activeTab : {})}} onClick={() => setActiveTab('profile')}>👤 Profile</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading...</div> : (
          <>
            {/* Dashboard Tab */}
            {activeTab === 'dashboard' && (
              <div style={styles.twoColumn}>
                {/* Left Column */}
                <div>
                  <div style={styles.card}>
                    <h3>📊 Today's Performance</h3>
                    <div style={styles.performanceItem}>
                      <span>Deliveries Completed:</span>
                      <span style={styles.performanceValue}>{Math.floor(Math.random() * 5) + 1}</span>
                    </div>
                    <div style={styles.performanceItem}>
                      <span>Hours Worked:</span>
                      <span style={styles.performanceValue}>{Math.floor(Math.random() * 6) + 2}h</span>
                    </div>
                    <div style={styles.performanceItem}>
                      <span>Distance Covered:</span>
                      <span style={styles.performanceValue}>{Math.floor(Math.random() * 50) + 10} miles</span>
                    </div>
                    <div style={styles.performanceItem}>
                      <span>Rating Received:</span>
                      <span style={styles.performanceValue}>⭐ 5.0</span>
                    </div>
                  </div>

                  <div style={styles.card}>
                    <h3>📍 Current Location</h3>
                    <div style={styles.locationInfo}>
                      <span>📌 {currentLocation.address}</span>
                      <button style={styles.updateLocationBtn} onClick={() => setShowLocationModal(true)}>Update</button>
                    </div>
                    <div style={styles.mapPlaceholder}>
                      🗺️ Map View - Live tracking active
                    </div>
                  </div>

                  <div style={styles.card}>
                    <h3>📈 Performance Stats</h3>
                    <div style={styles.metricItem}>
                      <span>Acceptance Rate:</span>
                      <div style={styles.progressBar}>
                        <div style={{ ...styles.progressFill, width: `${driverStats.acceptanceRate}%`, backgroundColor: '#10b981' }}></div>
                      </div>
                      <span>{driverStats.acceptanceRate}%</span>
                    </div>
                    <div style={styles.metricItem}>
                      <span>On-Time Rate:</span>
                      <div style={styles.progressBar}>
                        <div style={{ ...styles.progressFill, width: `${driverStats.onTimeRate}%`, backgroundColor: '#3b82f6' }}></div>
                      </div>
                      <span>{driverStats.onTimeRate}%</span>
                    </div>
                    <div style={styles.metricItem}>
                      <span>Customer Rating:</span>
                      <div style={styles.progressBar}>
                        <div style={{ ...styles.progressFill, width: `${(driverStats.rating / 5) * 100}%`, backgroundColor: '#f59e0b' }}></div>
                      </div>
                      <span>⭐ {driverStats.rating}</span>
                    </div>
                  </div>
                </div>

                {/* Right Column */}
                <div>
                  <div style={styles.card}>
                    <h3>📦 Quick Actions</h3>
                    <div style={styles.quickActions}>
                      <button style={styles.quickActionBtn} onClick={() => setActiveTab('available')}>Browse Available →</button>
                      <button style={styles.quickActionBtn} onClick={() => setShowLocationModal(true)}>Update Location →</button>
                      <button style={styles.quickActionBtn} onClick={() => setShowVehicleModal(true)}>Update Vehicle →</button>
                    </div>
                  </div>

                  <div style={styles.card}>
                    <h3>🚗 Active Jobs ({activeJobs.length})</h3>
                    {activeJobs.length === 0 ? (
                      <p style={styles.noData}>No active jobs. Check available deliveries!</p>
                    ) : (
                      activeJobs.map(job => (
                        <div key={job._id} style={styles.activeJobItem}>
                          <div><strong>{job.serviceName}</strong></div>
                          <div>Customer: {job.customerId?.firstName}</div>
                          <span style={getStatusBadge(job.status)}>{job.status}</span>
                        </div>
                      ))
                    )}
                  </div>

                  <div style={styles.card}>
                    <h3>💰 Today's Earnings Breakdown</h3>
                    <div style={styles.earningsBreakdown}>
                      <div>Base Deliveries: <strong>${Math.floor(todayEarnings * 0.8)}</strong></div>
                      <div>Tips: <strong>${Math.floor(todayEarnings * 0.2)}</strong></div>
                      <div>Bonuses: <strong>$0</strong></div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Available Deliveries Tab */}
            {activeTab === 'available' && (
              <div>
                <div style={styles.sectionHeader}>
                  <h2>📦 Available Deliveries ({availableDeliveries.length})</h2>
                  <span style={styles.onlineBadge}>🟢 You are {isOnline ? 'Online' : 'Offline'}</span>
                </div>

                {availableDeliveries.length === 0 ? (
                  <div style={styles.emptyState}>
                    <span style={styles.emptyIcon}>📦</span>
                    <h3>No Available Deliveries</h3>
                    <p>Check back soon for new concierge requests</p>
                  </div>
                ) : (
                  availableDeliveries.map(delivery => (
                    <div key={delivery._id} style={styles.deliveryCard}>
                      <div style={styles.deliveryHeader}>
                        <span style={styles.deliveryType}>🚗 Concierge Pickup</span>
                        <span style={getStatusBadge(delivery.status)}>{delivery.status}</span>
                      </div>

                      <div style={styles.deliveryContent}>
                        <div style={styles.pickupInfo}>
                          <span style={styles.infoIcon}>📍</span>
                          <div>
                            <strong>Pickup Location:</strong>
                            <p>{delivery.pickupAddress || delivery.customerId?.address || 'Customer address'}</p>
                            <span style={styles.distanceBadge}>{getDistanceText()}</span>
                          </div>
                        </div>

                        <div style={styles.arrowIcon}>↓</div>

                        <div style={styles.shopInfo}>
                          <span style={styles.infoIcon}>🔧</span>
                          <div>
                            <strong>Service Center:</strong>
                            <p>{delivery.providerId?.businessName || 'Auto Service Center'}</p>
                            <p>Service: {delivery.serviceName}</p>
                          </div>
                        </div>
                      </div>

                      <div style={styles.deliveryFooter}>
                        <div>
                          <span style={styles.etaBadge}>⏱️ ETA: {getEtaText()}</span>
                          <span style={styles.priceBadge}>💰 ${earnings.perDelivery}</span>
                        </div>
                        <button style={styles.acceptBtn} onClick={() => acceptDelivery(delivery._id)}>
                          Accept Delivery →
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Active Jobs Tab */}
            {activeTab === 'active' && (
              <div>
                <h2>🚗 Active Jobs ({activeJobs.length})</h2>
                {activeJobs.length === 0 ? (
                  <div style={styles.emptyState}>
                    <span style={styles.emptyIcon}>🚗</span>
                    <h3>No Active Jobs</h3>
                    <p>Accept a delivery to get started</p>
                  </div>
                ) : (
                  activeJobs.map(job => (
                    <div key={job._id} style={styles.activeCard}>
                      <div style={styles.activeHeader}>
                        <span style={styles.activeType}>🚗 Active Delivery</span>
                        <span style={getStatusBadge(job.status)}>{job.status}</span>
                      </div>

                      <div style={styles.progressSteps}>
                        <div style={{...styles.step, ...(job.status === 'confirmed' ? styles.stepActive : styles.stepCompleted)}}>
                          <span>1</span> Pickup
                        </div>
                        <div style={styles.stepLine}></div>
                        <div style={{...styles.step, ...(job.status === 'in-progress' ? styles.stepActive : job.status === 'confirmed' ? {} : styles.stepCompleted)}}>
                          <span>2</span> Drop-off
                        </div>
                        <div style={styles.stepLine}></div>
                        <div style={{...styles.step, ...(job.status === 'completed' ? styles.stepActive : {})}}>
                          <span>3</span> Complete
                        </div>
                      </div>

                      <div style={styles.jobDetails}>
                        <p><strong>Customer:</strong> {job.customerId?.firstName} {job.customerId?.lastName}</p>
                        <p><strong>Phone:</strong> {job.customerId?.phone || 'N/A'}</p>
                        <p><strong>Service:</strong> {job.serviceName}</p>
                        <p><strong>Shop:</strong> {job.providerId?.businessName}</p>
                        <p><strong>Pickup:</strong> {job.pickupAddress || 'Customer address'}</p>
                      </div>

                      <div style={styles.actionButtons}>
                        {job.status === 'confirmed' && (
                          <button style={styles.pickupBtn} onClick={() => updateDeliveryStatus(job._id, 'in-progress')}>
                            📍 Confirm Pickup
                          </button>
                        )}
                        {job.status === 'in-progress' && (
                          <button style={styles.completeBtn} onClick={() => updateDeliveryStatus(job._id, 'completed')}>
                            ✅ Complete Delivery
                          </button>
                        )}
                        <button style={styles.contactBtn}>📞 Contact Customer</button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* History Tab */}
            {activeTab === 'history' && (
              <div>
                <div style={styles.historyHeader}>
                  <h2>📋 Delivery History</h2>
                  <select style={styles.filterSelect} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
                    <option value="all">All</option>
                    <option value="completed">Completed</option>
                    <option value="cancelled">Cancelled</option>
                  </select>
                </div>
                {filteredHistory.length === 0 ? (
                  <div style={styles.emptyState}>No completed deliveries yet</div>
                ) : (
                  filteredHistory.map(delivery => (
                    <div key={delivery._id} style={styles.historyCard}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                          <p><strong>{delivery.serviceName}</strong></p>
                          <p>Customer: {delivery.customerId?.firstName} {delivery.customerId?.lastName}</p>
                          <p>📅 {new Date(delivery.bookingDate).toLocaleDateString()}</p>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                          <span style={getStatusBadge(delivery.status)}>{delivery.status}</span>
                          <p style={styles.earningText}>+${earnings.perDelivery}</p>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Earnings Tab */}
            {activeTab === 'earnings' && (
              <div>
                <div style={styles.earningsHeader}>
                  <h2>💰 Earnings Overview</h2>
                  <select style={styles.periodSelect}>
                    <option>This Week</option>
                    <option>This Month</option>
                    <option>This Year</option>
                  </select>
                </div>

                <div style={styles.earningsGrid}>
                  <div style={styles.earningsCard}>
                    <span style={styles.earningsIcon}>💰</span>
                    <h3>Total Earnings</h3>
                    <p style={styles.earningsAmount}>${earnings.total}</p>
                  </div>
                  <div style={styles.earningsCard}>
                    <span style={styles.earningsIcon}>📊</span>
                    <h3>This Week</h3>
                    <p style={styles.earningsAmount}>${earnings.weekly}</p>
                  </div>
                  <div style={styles.earningsCard}>
                    <span style={styles.earningsIcon}>🚗</span>
                    <h3>Total Deliveries</h3>
                    <p style={styles.earningsAmount}>{earnings.totalDeliveries}</p>
                  </div>
                  <div style={styles.earningsCard}>
                    <span style={styles.earningsIcon}>⭐</span>
                    <h3>Rating</h3>
                    <p style={styles.earningsAmount}>{driverStats.rating}</p>
                  </div>
                </div>

                {/* Daily Earnings Chart */}
                <div style={styles.card}>
                  <h3>📊 Daily Earnings (This Week)</h3>
                  <div style={styles.dailyChart}>
                    {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((day, i) => (
                      <div key={day} style={styles.chartBar}>
                        <div style={{ ...styles.barFill, height: `${Math.floor(Math.random() * 80) + 20}px` }}></div>
                        <span>{day}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div style={styles.infoCard}>
                  <h3>💡 How It Works</h3>
                  <ul style={styles.infoList}>
                    <li>💰 <strong>${earnings.perDelivery}</strong> per delivery + customer tips</li>
                    <li>🕐 Average delivery time: 30-45 minutes</li>
                    <li>📊 Payments processed weekly to your account</li>
                    <li>⭐ Maintain 4.5+ rating for bonus opportunities</li>
                    <li>🏆 Complete 50+ deliveries for elite status</li>
                  </ul>
                </div>
              </div>
            )}

            {/* Vehicle Tab */}
            {activeTab === 'vehicle' && (
              <div style={styles.vehicleContainer}>
                <div style={styles.vehicleHeader}>
                  <h2>🚗 My Vehicle</h2>
                  <button style={styles.editBtn} onClick={() => setShowVehicleModal(true)}>✏️ Edit</button>
                </div>

                <div style={styles.vehicleCard}>
                  <div style={styles.vehicleIcon}>🚗</div>
                  <div style={styles.vehicleDetails}>
                    <h3>{vehicleInfo.year} {vehicleInfo.model}</h3>
                    <p>Color: {vehicleInfo.color}</p>
                    <p>License Plate: {vehicleInfo.plate}</p>
                  </div>
                </div>

                <div style={styles.card}>
                  <h3>📋 Vehicle Documents</h3>
                  <div style={styles.documentItem}>
                    <span>Insurance Certificate</span>
                    <span style={styles.verifiedBadge}>✅ Verified</span>
                  </div>
                  <div style={styles.documentItem}>
                    <span>Vehicle Registration</span>
                    <span style={styles.pendingBadge}>⏳ Pending</span>
                  </div>
                  <div style={styles.documentItem}>
                    <span>Inspection Certificate</span>
                    <span style={styles.verifiedBadge}>✅ Verified</span>
                  </div>
                </div>
              </div>
            )}

            {/* Profile Tab */}
            {activeTab === 'profile' && (
              <div style={styles.profileContainer}>
                <div style={styles.profileHeader}>
                  <img src={`https://ui-avatars.com/api/?background=2563eb&color=fff&name=${user?.firstName} ${user?.lastName}&size=100`} alt="avatar" style={styles.profileAvatar} />
                  <div>
                    <h2>{user?.firstName} {user?.lastName}</h2>
                    <p>⭐ {driverStats.rating} • {driverStats.totalRatings} reviews</p>
                    <p>Member since {new Date(user?.createdAt || Date.now()).toLocaleDateString()}</p>
                  </div>
                </div>
                <div style={styles.profileInfo}>
                  <div><strong>📧 Email:</strong> {user?.email}</div>
                  <div><strong>📞 Phone:</strong> {user?.phone}</div>
                  <div><strong>🚗 Driver's License:</strong> {user?.driversLicense || 'DL12345678'}</div>
                  <div><strong>📦 Total Deliveries:</strong> {earnings.totalDeliveries}</div>
                  <div><strong>✅ Acceptance Rate:</strong> {driverStats.acceptanceRate}%</div>
                  <div><strong>⏱️ On-Time Rate:</strong> {driverStats.onTimeRate}%</div>
                </div>
                <button style={styles.editProfileBtn}>Edit Profile</button>
              </div>
            )}
          </>
        )}
      </div>

      {/* Location Modal */}
      {showLocationModal && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2>📍 Update Location</h2>
            <div style={styles.mapContainer}>
              <div style={styles.mapPlaceholderLarge}>
                🗺️ Live Map - Drag to update location
              </div>
            </div>
            <input style={styles.input} type="text" placeholder="Address" value={currentLocation.address} onChange={(e) => setCurrentLocation({...currentLocation, address: e.target.value})} />
            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={() => { updateDriverLocation(currentLocation.lat, currentLocation.lng); setShowLocationModal(false); toast.success('Location updated!'); }}>Save Location</button>
              <button style={styles.cancelBtn} onClick={() => setShowLocationModal(false)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <div style={styles.modal}>
          <div style={styles.modalContentSmall}>
            <h2>🚗 Update Vehicle Info</h2>
            <form onSubmit={updateVehicleInfo}>
              <input style={styles.input} type="text" placeholder="Vehicle Model" value={vehicleInfo.model} onChange={(e) => setVehicleInfo({...vehicleInfo, model: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Color" value={vehicleInfo.color} onChange={(e) => setVehicleInfo({...vehicleInfo, color: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="License Plate" value={vehicleInfo.plate} onChange={(e) => setVehicleInfo({...vehicleInfo, plate: e.target.value})} required />
              <input style={styles.input} type="number" placeholder="Year" value={vehicleInfo.year} onChange={(e) => setVehicleInfo({...vehicleInfo, year: e.target.value})} required />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Save</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowVehicleModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

